contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint x) public payable {
        // top-level state-changing call: first selfdestruct (must not revert, since test contract is owner)
        c.sudicideAnyone(); if (__ESBMC_reverted()) return;

        // record observable value after the first call
        uint balAfterFirst = address(c).balance;

        // second top-level state-changing call: should also complete without revert
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: because the test contract is the owner, calling sudicideAnyone
        // never reverts, and after selfdestruct the contract's Ether balance remains unchanged.
        assert(!reverted && address(c).balance == balAfterFirst);
    }

    receive() external payable {}
}

